SELECT COUNT(*)
FROM ${table}
WHERE user_id = #{userId}

    AND ${pk} = #{eventId}


    AND TIMESTAMP(start_date, start_time) >= #{from}


    AND TIMESTAMP(end_date, end_time) <= #{to}

SELECT event_id, user_id, title, type,
       start_date, start_time, end_date, end_time,
       location, description, created_at, updated_at, meeting_id
FROM ${table}
WHERE user_id = #{userId}

    AND ${pk} = #{eventId}


    AND TIMESTAMP(start_date, start_time) >= #{from}


    AND TIMESTAMP(end_date, end_time) <= #{to}

ORDER BY start_date DESC, start_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT event_id, user_id, title, type,
       start_date, start_time, end_date, end_time,
       location, description, created_at, updated_at, meeting_id
FROM ${table}
WHERE ${pk} = #{eventId}
  AND user_id = #{userId}

